package com.dawnrise.school.communication;

import com.dawnrise.school.school.exception.ResourceNotFoundException;
import com.dawnrise.school.leave.AcademicWorkingDayClient;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
import java.time.OffsetDateTime;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.*;

@Service
public class ParentConversationService {
    private final NamedParameterJdbcTemplate db; private final CommunicationDirectoryGateway directory; private final ObjectMapper json; private final AcademicWorkingDayClient workingDays;
    public ParentConversationService(NamedParameterJdbcTemplate db,CommunicationDirectoryGateway directory,ObjectMapper json,AcademicWorkingDayClient workingDays){this.db=db;this.directory=directory;this.json=json;this.workingDays=workingDays;}

    public List<ParentConversationDtos.Contact> contacts(long org,long guardian,long student,String query){
        requireGuardian(org,guardian,student);
        Set<Long> assigned=new LinkedHashSet<>();directory.parentContacts(org,student).forEach(contact->assigned.add(contact.userId()));
        List<Configured> configured=db.query("SELECT user_id,category,display_label FROM parent_communication_contacts WHERE organization_id=:org AND active AND contact_type='PARENT_FACING' ORDER BY display_label,category",new MapSqlParameterSource("org",org),(rs,n)->new Configured(rs.getLong(1),rs.getString(2),rs.getString(3)));
        Set<Long> ids=new LinkedHashSet<>(assigned);configured.forEach(value->ids.add(value.user));if(ids.isEmpty())return List.of();
        Map<Long,CommunicationDirectoryGateway.IdentityUser> users=new LinkedHashMap<>();directory.searchUsers(org,query,0,50,ids).items().forEach(user->users.put(user.id(),user));List<ParentConversationDtos.Contact> result=new ArrayList<>();
        for(Long id:assigned){var user=users.get(id);if(user!=null)result.add(new ParentConversationDtos.Contact(id,user.displayName(),"Assigned teacher","GENERAL","ASSIGNED_TEACHER"));}
        for(Configured value:configured){var user=users.get(value.user);if(user!=null)result.add(new ParentConversationDtos.Contact(value.user,user.displayName(),value.label,value.category,"CONFIGURED_STAFF"));}
        return List.copyOf(result);
    }

    @Transactional public ParentConversationDtos.Thread create(long org,long guardian,String key,ParentConversationDtos.Create input){
        requireKey(key);requireGuardian(org,guardian,input.studentUserId());Policy policy=policy(org);
        int open=count("SELECT COUNT(*) FROM parent_communication_threads WHERE organization_id=:org AND guardian_user_id=:actor AND status='OPEN'",org,guardian);
        int recent=count("SELECT COUNT(*) FROM parent_communication_threads WHERE organization_id=:org AND guardian_user_id=:actor AND created_at>CURRENT_TIMESTAMP-INTERVAL '7 days'",org,guardian);
        if(open>=policy.open)throw new IllegalStateException("Resolve an open conversation before starting another");
        if(recent>=policy.week)throw new IllegalStateException("The weekly new-conversation limit has been reached");
        var contact=contacts(org,guardian,input.studentUserId(),"").stream().filter(value->value.userId()==input.contactUserId()).findFirst().orElseThrow(()->new IllegalArgumentException("Contact is not available for this student"));
        if("CONFIGURED_STAFF".equals(contact.kind())&&!contact.category().equalsIgnoreCase(input.category()))throw new IllegalArgumentException("Contact is not configured for this category");
        OffsetDateTime eligible=headEligibleAt(org,policy.days);long id;try{id=Objects.requireNonNull(db.queryForObject("INSERT INTO parent_communication_threads(organization_id,guardian_user_id,student_user_id,contact_user_id,contact_kind,category,subject,head_eligible_at) VALUES(:org,:actor,:student,:contact,:kind,:category,:subject,:eligible) RETURNING id",params(org,guardian).addValue("student",input.studentUserId()).addValue("contact",input.contactUserId()).addValue("kind",contact.kind()).addValue("category",plain(input.category(),32)).addValue("subject",plain(input.subject(),160)).addValue("eligible",eligible),Long.class));}catch(DuplicateKeyException exception){throw new IllegalStateException("An open conversation already exists for this student, contact, and category");}
        db.update("INSERT INTO parent_communication_participants(organization_id,thread_id,user_id,participant_role) VALUES(:org,:id,:guardian,'GUARDIAN'),(:org,:id,:contact,'CONTACT')",new MapSqlParameterSource("org",org).addValue("id",id).addValue("guardian",guardian).addValue("contact",input.contactUserId()));
        addMessage(org,guardian,id,key,input.message());audit(org,id,guardian,"CREATED",Map.of());return get(org,guardian,id);
    }

    @Transactional public ParentConversationDtos.Thread createDirect(long org,long actor,boolean schoolWide,String key,ParentConversationDtos.CreateDirect input){
        requireKey(key);if(actor==input.recipientUserId())throw new IllegalArgumentException("Choose another recipient");directory.resolveUsers(org,Set.of(actor,input.recipientUserId()));
        if(!schoolWide){Set<Long> students=directory.scopeStudents(org,actor,false);Set<Long> allowed=new LinkedHashSet<>(directory.identityAudience(org,"STAFF",null));allowed.addAll(students);if(!students.isEmpty())allowed.addAll(directory.guardians(org,students));if(!allowed.contains(input.recipientUserId()))throw new IllegalArgumentException("Recipient is outside the actor assignment scope");}
        long id;try{id=Objects.requireNonNull(db.queryForObject("INSERT INTO parent_communication_threads(organization_id,guardian_user_id,student_user_id,contact_user_id,contact_kind,category,subject,head_eligible_at,thread_kind) VALUES(:org,:actor,:actor,:recipient,'DIRECT_STAFF','DIRECT',:subject,CURRENT_TIMESTAMP,'STAFF_DIRECT') RETURNING id",params(org,actor).addValue("recipient",input.recipientUserId()).addValue("subject",plain(input.subject(),160)),Long.class));}catch(DuplicateKeyException exception){throw new IllegalStateException("An open conversation already exists with this recipient and subject");}
        db.update("INSERT INTO parent_communication_participants(organization_id,thread_id,user_id,participant_role) VALUES(:org,:id,:actor,'INITIATOR'),(:org,:id,:recipient,'RECIPIENT')",params(org,actor).addValue("id",id).addValue("recipient",input.recipientUserId()));
        addMessage(org,actor,id,key,input.message());audit(org,id,actor,"DIRECT_CREATED",Map.of("recipientUserId",input.recipientUserId()));return get(org,actor,id);
    }

    @Transactional public ParentConversationDtos.Thread reply(long org,long actor,long id,String key,String body){requireParticipant(org,actor,id);requireCurrentParticipant(org,actor,id);addMessage(org,actor,id,key,body);return get(org,actor,id);}
    @Transactional public ParentConversationDtos.Thread markRead(long org,long actor,long id){requireParticipant(org,actor,id);db.update("UPDATE parent_communication_participants SET last_read_message_id=(SELECT MAX(id) FROM parent_communication_messages WHERE organization_id=:org AND thread_id=:id) WHERE organization_id=:org AND thread_id=:id AND user_id=:actor",params(org,actor).addValue("id",id));return get(org,actor,id);}
    @Transactional public ParentConversationDtos.Thread requestHead(long org,long guardian,long id){var thread=get(org,guardian,id);if(!thread.headEscalationAvailable())throw new IllegalStateException("Head escalation is not available yet");Long head=db.query("SELECT user_id FROM parent_communication_contacts WHERE organization_id=:org AND active AND contact_type='ACADEMIC_HEAD' AND category IN(:category,'GENERAL') ORDER BY CASE WHEN category=:category THEN 0 ELSE 1 END,id LIMIT 1",new MapSqlParameterSource("org",org).addValue("category",thread.category()),(rs,n)->rs.getLong(1)).stream().findFirst().orElseThrow(()->new IllegalStateException("No academic head is configured for this category"));db.update("INSERT INTO parent_communication_participants(organization_id,thread_id,user_id,participant_role) VALUES(:org,:id,:head,'HEAD') ON CONFLICT DO NOTHING",new MapSqlParameterSource("org",org).addValue("id",id).addValue("head",head));db.update("UPDATE parent_communication_threads SET escalation_level='HEAD',updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE organization_id=:org AND id=:id",new MapSqlParameterSource("org",org).addValue("id",id));audit(org,id,guardian,"ESCALATED_TO_HEAD",Map.of());notify(org,id,guardian,head,"Conversation escalated","A parent communication requires your review");return get(org,guardian,id);}
    @Transactional public ParentConversationDtos.Thread resolve(long org,long actor,long id){requireParticipant(org,actor,id);db.update("UPDATE parent_communication_threads SET status='RESOLVED',updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE organization_id=:org AND id=:id",new MapSqlParameterSource("org",org).addValue("id",id));audit(org,id,actor,"RESOLVED",Map.of());return get(org,actor,id);}
    @Transactional public ParentConversationDtos.Thread escalatePrincipal(long org,long actor,long id){Integer head=db.queryForObject("SELECT COUNT(*) FROM parent_communication_participants WHERE organization_id=:org AND thread_id=:id AND user_id=:actor AND participant_role='HEAD' AND left_at IS NULL",params(org,actor).addValue("id",id),Integer.class);if(head==null||head!=1)throw new ResourceNotFoundException("Conversation not found");Long principal=directory.identityAudience(org,"ROLE","PRINCIPAL").stream().findFirst().orElseThrow(()->new IllegalStateException("No active principal is configured"));db.update("INSERT INTO parent_communication_participants(organization_id,thread_id,user_id,participant_role) VALUES(:org,:id,:principal,'PRINCIPAL') ON CONFLICT DO NOTHING",new MapSqlParameterSource("org",org).addValue("id",id).addValue("principal",principal));db.update("UPDATE parent_communication_threads SET escalation_level='PRINCIPAL',principal_authorized_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE organization_id=:org AND id=:id AND escalation_level='HEAD'",new MapSqlParameterSource("org",org).addValue("id",id));audit(org,id,actor,"ESCALATED_TO_PRINCIPAL",Map.of());notify(org,id,actor,principal,"Conversation escalated","A parent communication was escalated for principal review");return get(org,actor,id);}
    public List<ParentConversationDtos.Thread> list(long org,long actor){return db.queryForList("SELECT thread_id FROM parent_communication_participants WHERE organization_id=:org AND user_id=:actor AND left_at IS NULL ORDER BY thread_id DESC LIMIT 50",params(org,actor),Long.class).stream().map(id->get(org,actor,id)).toList();}
    public ParentConversationDtos.Thread get(long org,long actor,long id){requireParticipant(org,actor,id);return db.query("SELECT t.*,p.last_read_message_id FROM parent_communication_threads t JOIN parent_communication_participants p ON p.organization_id=t.organization_id AND p.thread_id=t.id AND p.user_id=:actor WHERE t.organization_id=:org AND t.id=:id",params(org,actor).addValue("id",id),(rs,n)->{String kind=rs.getString("thread_kind");long other="STAFF_DIRECT".equals(kind)?otherParticipant(org,id,actor):rs.getLong("contact_user_id");return new ParentConversationDtos.Thread(rs.getLong("id"),rs.getLong("student_user_id"),rs.getLong("contact_user_id"),name(org,other),rs.getString("category"),rs.getString("subject"),rs.getString("status"),rs.getString("escalation_level"),"PARENT".equals(kind)&&"OPEN".equals(rs.getString("status"))&&rs.getObject("head_eligible_at",OffsetDateTime.class).isBefore(OffsetDateTime.now())&&"NONE".equals(rs.getString("escalation_level")),unread(org,id,(Long)rs.getObject("last_read_message_id")),rs.getObject("last_message_at",OffsetDateTime.class),rs.getLong("version"),messages(org,id),kind);}).getFirst();}
    @Transactional public void configureContact(long org,long actor,ParentConversationDtos.ContactInput input){directory.resolveUsers(org,Set.of(input.userId()));String type=Set.of("PARENT_FACING","ACADEMIC_HEAD").contains(input.contactType())?input.contactType():"";if(type.isEmpty())throw new IllegalArgumentException("Unsupported contact type");var page=directory.searchUsers(org,"",0,1,Set.of(input.userId()));if(page.items().isEmpty())throw new IllegalArgumentException("Contact is unavailable");Set<String> roles=Set.copyOf(page.items().getFirst().roles());if("ACADEMIC_HEAD".equals(type)&&roles.stream().noneMatch(Set.of("ADMIN","VICE_PRINCIPAL")::contains))throw new IllegalArgumentException("Academic head must be an active admin or vice principal");if("PARENT_FACING".equals(type)&&roles.stream().anyMatch(Set.of("STUDENT","PARENT","PRINCIPAL","GOVERNING_AUTHORITY")::contains))throw new IllegalArgumentException("This role cannot be configured as a parent-facing contact");db.update("INSERT INTO parent_communication_contacts(organization_id,user_id,category,contact_type,display_label,created_by_user_id) VALUES(:org,:user,:category,:type,:label,:actor) ON CONFLICT(organization_id,user_id,category,contact_type) DO UPDATE SET display_label=EXCLUDED.display_label,active=TRUE",params(org,actor).addValue("user",input.userId()).addValue("category",plain(input.category(),32)).addValue("type",type).addValue("label",plain(input.displayLabel(),120)));}
    @Transactional public void configurePolicy(long org,long actor,ParentConversationDtos.PolicyInput input){if(input.maxOpenThreads()>20||input.maxNewThreads7Days()>50||input.headEscalationSchoolDays()>10)throw new IllegalArgumentException("Communication policy is outside supported limits");db.update("INSERT INTO parent_communication_policies(organization_id,max_open_threads,max_new_threads_7_days,head_escalation_school_days,updated_by_user_id) VALUES(:org,:open,:week,:days,:actor) ON CONFLICT(organization_id) DO UPDATE SET max_open_threads=EXCLUDED.max_open_threads,max_new_threads_7_days=EXCLUDED.max_new_threads_7_days,head_escalation_school_days=EXCLUDED.head_escalation_school_days,updated_by_user_id=EXCLUDED.updated_by_user_id,updated_at=CURRENT_TIMESTAMP",params(org,actor).addValue("open",input.maxOpenThreads()).addValue("week",input.maxNewThreads7Days()).addValue("days",input.headEscalationSchoolDays()));}
    private void addMessage(long org,long actor,long id,String key,String body){requireKey(key);String text=plain(body,4000);Long message=db.query("INSERT INTO parent_communication_messages(organization_id,thread_id,sender_user_id,body,idempotency_key) VALUES(:org,:id,:actor,:body,:key) ON CONFLICT(organization_id,sender_user_id,idempotency_key) DO NOTHING RETURNING id",params(org,actor).addValue("id",id).addValue("body",text).addValue("key",key),(rs,n)->rs.getLong(1)).stream().findFirst().orElse(null);if(message==null)return;db.update("UPDATE parent_communication_threads SET last_message_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE organization_id=:org AND id=:id",new MapSqlParameterSource("org",org).addValue("id",id));db.update("UPDATE parent_communication_participants SET last_read_message_id=:message WHERE organization_id=:org AND thread_id=:id AND user_id=:actor",params(org,actor).addValue("id",id).addValue("message",message));List<Long> recipients=db.queryForList("SELECT user_id FROM parent_communication_participants WHERE organization_id=:org AND thread_id=:id AND user_id<>:actor AND left_at IS NULL",params(org,actor).addValue("id",id),Long.class);for(Long recipient:recipients)notify(org,id,actor,recipient,"New school communication",text);audit(org,id,actor,"MESSAGE_SENT",Map.of("messageId",message));}
    private void notify(long org,long thread,long actor,long recipient,String heading,String context){try{db.update("INSERT INTO school_notification_outbox(source_type,source_id,organization_id,source_event_id,event_type,importance,heading,context,audience_spec,recipient_user_ids,available_at) VALUES('CONVERSATION',:thread,:org,:event,'PARENT_COMMUNICATION_MESSAGE','NORMAL',:heading,:context,'[]'::jsonb,CAST(:recipients AS JSONB),CURRENT_TIMESTAMP)",new MapSqlParameterSource("thread",thread).addValue("org",org).addValue("event","conversation:"+thread+":"+UUID.randomUUID()).addValue("heading",heading).addValue("context",context.length()>500?context.substring(0,500):context).addValue("recipients",json.writeValueAsString(Set.of(recipient))));}catch(Exception e){throw new IllegalStateException("Message notification could not be queued",e);}}
    private void requireGuardian(long org,long guardian,long student){if(!directory.guardians(org,Set.of(student)).contains(guardian))throw new ResourceNotFoundException("Linked student not found");}
    private void requireParticipant(long org,long actor,long id){Integer value=db.queryForObject("SELECT COUNT(*) FROM parent_communication_participants WHERE organization_id=:org AND user_id=:actor AND thread_id=:id AND left_at IS NULL",params(org,actor).addValue("id",id),Integer.class);if(value==null||value!=1)throw new ResourceNotFoundException("Conversation not found");}
    private void requireCurrentParticipant(long org,long actor,long id){var row=db.queryForMap("SELECT t.guardian_user_id,t.student_user_id,t.contact_user_id,t.contact_kind,t.thread_kind,p.participant_role FROM parent_communication_threads t JOIN parent_communication_participants p ON p.organization_id=t.organization_id AND p.thread_id=t.id AND p.user_id=:actor WHERE t.organization_id=:org AND t.id=:id",params(org,actor).addValue("id",id));if("STAFF_DIRECT".equals(String.valueOf(row.get("thread_kind")))){if(!directory.senderAuthority(org,actor).active())throw new IllegalStateException("This participant is no longer active");return;}String role=String.valueOf(row.get("participant_role"));long student=((Number)row.get("student_user_id")).longValue();if("GUARDIAN".equals(role)){requireGuardian(org,actor,student);return;}if(!directory.senderAuthority(org,actor).active())throw new IllegalStateException("This participant is no longer active");if("CONTACT".equals(role)){String kind=String.valueOf(row.get("contact_kind"));if("ASSIGNED_TEACHER".equals(kind)&&directory.parentContacts(org,student).stream().noneMatch(contact->contact.userId()==actor))throw new IllegalStateException("This teacher is no longer assigned to the student");if("CONFIGURED_STAFF".equals(kind)&&count("SELECT COUNT(*) FROM parent_communication_contacts WHERE organization_id=:org AND user_id=:actor AND active",org,actor)==0)throw new IllegalStateException("This staff contact is no longer configured");}}
    private int count(String sql,long org,long actor){Integer value=db.queryForObject(sql,params(org,actor),Integer.class);return value==null?0:value;}
    private int unread(long org,long id,Long read){Integer value=db.queryForObject("SELECT COUNT(*) FROM parent_communication_messages WHERE organization_id=:org AND thread_id=:id AND id>:read",new MapSqlParameterSource("org",org).addValue("id",id).addValue("read",read==null?0:read),Integer.class);return value==null?0:value;}
    private List<ParentConversationDtos.Message> messages(long org,long id){return db.query("SELECT id,sender_user_id,body,created_at FROM (SELECT id,sender_user_id,body,created_at FROM parent_communication_messages WHERE organization_id=:org AND thread_id=:id ORDER BY id DESC LIMIT 100) recent ORDER BY id",new MapSqlParameterSource("org",org).addValue("id",id),(rs,n)->new ParentConversationDtos.Message(rs.getLong(1),rs.getLong(2),rs.getString(3),rs.getObject(4,OffsetDateTime.class)));}
    private String name(long org,long user){var page=directory.searchUsers(org,"",0,1,Set.of(user));return page.items().isEmpty()?"School contact":page.items().getFirst().displayName();}
    private long otherParticipant(long org,long id,long actor){return db.queryForObject("SELECT user_id FROM parent_communication_participants WHERE organization_id=:org AND thread_id=:id AND user_id<>:actor AND left_at IS NULL ORDER BY user_id LIMIT 1",params(org,actor).addValue("id",id),Long.class);}
    private Policy policy(long org){return db.query("SELECT max_open_threads,max_new_threads_7_days,head_escalation_school_days FROM parent_communication_policies WHERE organization_id=:org",new MapSqlParameterSource("org",org),(rs,n)->new Policy(rs.getInt(1),rs.getInt(2),rs.getInt(3))).stream().findFirst().orElse(new Policy(3,5,2));}
    private OffsetDateTime headEligibleAt(long org,int days){LocalDate today=LocalDate.now();var dates=workingDays.days(org,today.plusDays(1),today.plusDays(30)).workingDates();if(dates.size()<days)throw new IllegalStateException("Academic calendar cannot calculate the escalation date");return dates.get(days-1).plusDays(1).atStartOfDay().atOffset(ZoneOffset.UTC);}
    private String plain(String value,int max){String text=value==null?"":value.trim();if(text.isEmpty()||text.length()>max||text.contains("<")||text.contains(">"))throw new IllegalArgumentException("Communication text is invalid");return text;}
    private void requireKey(String key){if(key==null||!key.matches("[A-Za-z0-9._:-]{8,120}"))throw new IllegalArgumentException("A valid Idempotency-Key header is required");}
    private MapSqlParameterSource params(long org,long actor){return new MapSqlParameterSource("org",org).addValue("actor",actor);}
    private void audit(long org,long id,long actor,String action,Map<String,Object> metadata){try{db.update("INSERT INTO parent_communication_audit(organization_id,thread_id,actor_user_id,action,metadata) VALUES(:org,:id,:actor,:action,CAST(:metadata AS JSONB))",params(org,actor).addValue("id",id).addValue("action",action).addValue("metadata",json.writeValueAsString(metadata)));}catch(Exception e){throw new IllegalStateException("Communication audit could not be recorded",e);}}
    private record Policy(int open,int week,int days){}
    private record Configured(long user,String category,String label){}
}
